/**
 * Confluence Node - Version 1
 * Discriminator: resource=search, operation=query
 */


interface Credentials {
  confluenceCloudOAuth2Api: CredentialReference;
  atlassianServiceAccountApi: CredentialReference;
}

/** Search content with a CQL query */
export type ConfluenceV1SearchQueryParams = {
  resource: 'search';
  operation: 'query';
  authentication?: 'cloudOAuth2' | 'serviceAccount';
/**
 * The Confluence site to use. Can be left empty when the connection has access to exactly one site.
 * @searchListMethod getSites
 * @default {"mode":"list","value":""}
 */
    site?: { __rl: true; mode: 'list' | 'url'; value: string; cachedResultName?: string };
/**
 * The CQL query to run. See &lt;a href="https://developer.atlassian.com/cloud/confluence/advanced-searching-using-cql/" target="_blank"&gt;Atlassian's CQL reference&lt;/a&gt; for the syntax.
 */
    cql: string | Expression<string>;
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 100
 */
    limit?: number | Expression<number>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** Comma-separated list of extra fields to expand on each search result
     */
    additionalExpandFields?: string | Expression<string>;
    /** Only match content in these statuses
     * @default []
     */
    contentStatuses?: Array<'archived' | 'current' | 'draft'>;
    /** Whether each result carries its full storage-format body (content.body.storage), fetched on the same request. Only applies to content results such as pages; space and user results have no body.
     * @default false
     */
    fetchFullPageContent?: boolean | Expression<boolean>;
  };
};

export type ConfluenceV1SearchQueryNode = {
  type: 'n8n-nodes-base.confluence';
  version: 1;
  config: NodeConfig<ConfluenceV1SearchQueryParams> & { credentials?: Credentials };
};